/* code box with several highlighted lines */
const codeHL = (lines, on, lang) => `<pre class="codebox" style="padding-left:6px"><code>${lines.map((l, i) => `<span style="display:block;${on.has(i) ? "background:var(--accent-bg);box-shadow:inset 3px 0 var(--accent);" : ""}padding-left:6px">${(lang === "text" ? ML.esc(l) : ML.hl(l)) || " "}</span>`).join("")}</code></pre>`;
